import { chromium } from "npm:playwright";

const browser = await chromium.launch();
const page = await browser.newPage();
await page.goto("https://the-internet.herokuapp.com/iframe");

blocks.text:
await page.goto("https://the-internet.herokuapp.com/nested_frames");

const middle = page
  .frameLocator("frame[name='frame-top']")
  .frameLocator("frame[name='frame-middle']")
  .locator("#content");
console.log("middle:", JSON.stringify((await middle.innerText()).trim()));

// frame-bottom is a SIBLING of frame-top, so it hangs off the page directly.
const bottom = page.frameLocator("frame[name='frame-bottom']").locator("body");
console.log("bottom:", JSON.stringify((await bottom.innerText()).trim()));

console.log(
  "bottom via top:",
  await page.frameLocator("frame[name='frame-top']").locator("frame[name='frame-bottom']").count(),
);

await page.goto("https://the-internet.herokuapp.com/hovers");

const figure = page.locator(".figure").first();
const caption = figure.locator(".figcaption");

console.log("figures on the page:", await page.locator(".figure").count());
console.log("caption visible before hover:", await caption.isVisible());

await figure.hover();

console.log("caption visible after hover: ", await caption.isVisible());
console.log("caption text:", JSON.stringify((await caption.innerText()).replace(/\s+/g, " ").trim()));

await page.goto("https://the-internet.herokuapp.com/context_menu");

// Register the listener BEFORE the click. The dialog blocks the page, so waiting
// until afterwards is already too late.
let dialogMessage = "";
page.once("dialog", async (dialog) => {
  dialogMessage = dialog.message();
  await dialog.accept();
});

await page.locator("#hot-spot").click({ button: "right" });
await page.waitForTimeout(500);      // explore cells only; the spec polls instead
console.log("dialog said:", JSON.stringify(dialogMessage));

// The rest of the family lives in the same options object.
const hotSpot = page.locator("#hot-spot");
await hotSpot.click({ button: "left" });
await hotSpot.dblclick();
await hotSpot.click({ delay: 150 });
console.log("left, double and delayed clicks all completed");

await page.goto("https://the-internet.herokuapp.com/drag_and_drop");

const columnA = page.locator("#column-a");
const columnB = page.locator("#column-b");

console.log("A header before:", await columnA.locator("header").innerText());
await columnA.dragTo(columnB);
console.log("A header after: ", await columnA.locator("header").innerText());

await browser.close();

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template
// literal — see Week 4 Day 1.1, concept 2.

await writeProjectFile("week4/generated/day2-frames.spec.ts", `// Week 4, Day 2 — reaching inside a frame.
//
// Uses the-internet.herokuapp.com because it has purpose-built single and nested
// frames. The source session drove a real bank's netbanking login page, which is
// not something course material should automate. Every selector below was probed.
//
// Written by a cell in week4/day2_2.ipynb. Run it yourself:
//   npx playwright test week4/generated/day2-frames.spec.ts
import { test, expect } from "@playwright/test";

const IFRAME = "https://the-internet.herokuapp.com/iframe";
const NESTED = "https://the-internet.herokuapp.com/nested_frames";

test.describe("Frames", () => {
  test("Step 1 — the element is visible but unreachable from the page", async ({ page }) => {
    await page.goto(IFRAME);

    // You can see the editor. The page cannot see into it.
    await expect(page.locator("iframe")).toHaveCount(1);
    await expect(page.locator("#tinymce")).toHaveCount(0);

    // This is the failure students spend twenty minutes on: the locator is
    // correct, the element exists on screen, and the count is still zero.
  });

  test("Step 2 — frameLocator crosses the boundary", async ({ page }) => {
    await page.goto(IFRAME);

    const editor = page.frameLocator("#mce_0_ifr").locator("body");

    await expect(editor).toHaveCount(1);
    await expect(editor).toContainText("Your content goes here.");
  });

  test("Step 3 — two failures that look alike and are not", async ({ page }) => {
    await page.goto(IFRAME);

    // (a) Correct locator, wrong side of the boundary. Nothing matches, so it
    //     spends the whole deadline waiting: a TIMEOUT.
    let outside = "";
    try {
      await page.locator("#tinymce").click({ timeout: 2000 });
    } catch (error) {
      outside = (error as Error).message;
    }
    expect(outside).toContain("Timeout");

    // (b) Correct side of the boundary, but this editor is read-only. Playwright
    //     found the element and refused the action: a DIFFERENT error, and it
    //     arrives immediately rather than after a deadline.
    let inside = "";
    try {
      await page.frameLocator("#mce_0_ifr").locator("body").fill("nope", { timeout: 2000 });
    } catch (error) {
      inside = (error as Error).message;
    }
    expect(inside).toContain("not an <input>");
    expect(inside).not.toContain("Timeout");

    // Read the error before changing the locator. A timeout means "I never found
    // it"; anything else means "I found it and could not do that to it".
  });

  test("Step 4 — nested frames need one hop each", async ({ page }) => {
    await page.goto(NESTED);

    // frame-top holds three more frames. Each boundary is its own frameLocator.
    const middle = page
      .frameLocator("frame[name='frame-top']")
      .frameLocator("frame[name='frame-middle']")
      .locator("#content");

    await expect(middle).toHaveText("MIDDLE");
  });

  test("Step 5 — a sibling frame is reached from the page, not from its neighbour", async ({ page }) => {
    await page.goto(NESTED);

    // frame-bottom is a sibling of frame-top, so it hangs off the page directly.
    const bottom = page.frameLocator("frame[name='frame-bottom']").locator("body");
    await expect(bottom).toContainText("BOTTOM");

    // Chaining through frame-top would never find it — the hierarchy matters.
    await expect(
      page.frameLocator("frame[name='frame-top']").locator("frame[name='frame-bottom']")
    ).toHaveCount(0);
  });

  test("Step 6 — frames auto-wait like any other locator", async ({ page }) => {
    await page.goto(IFRAME);

    // No explicit wait for the frame to load. frameLocator resolves lazily, so
    // the assertion retries until the frame and its contents exist.
    await expect(page.frameLocator("#mce_0_ifr").locator("body")).toBeVisible();
  });
});
`);

await runSpec("week4/generated/day2-frames.spec.ts");

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

