await writeProjectFile("week4/generated/day2-mouse-actions.spec.ts", `// Week 4, Day 2 — mouse actions.
//
// These use the-internet.herokuapp.com because they need hover menus, a
// right-click target and a drag surface. The banking app has none of those, and
// the sites the source video used (yatra.com, a Spree store) are a live
// commercial site and a server that was down during the session — neither is
// safe to build a lesson on. Every selector below was probed first.
//
// Written by a cell in week4/day2_2.ipynb. Run it yourself:
//   npx playwright test week4/generated/day2-mouse-actions.spec.ts
import { test, expect } from "@playwright/test";

const HOVERS = "https://the-internet.herokuapp.com/hovers";
const CONTEXT = "https://the-internet.herokuapp.com/context_menu";
const DRAG = "https://the-internet.herokuapp.com/drag_and_drop";

test.describe("Mouse actions", () => {
  test("Step 1 — hover reveals what was hidden", async ({ page }) => {
    await page.goto(HOVERS);

    const firstFigure = page.locator(".figure").first();
    const caption = firstFigure.locator(".figcaption");

    // Hidden until the pointer arrives.
    await expect(caption).toBeHidden();

    await firstFigure.hover();

    await expect(caption).toBeVisible();
    await expect(caption).toContainText("name: user1");
  });

  test("Step 2 — hover is one call, not three", async ({ page }) => {
    await page.goto(HOVERS);

    // Both forms work. The locator form is preferred: it auto-waits and reads
    // consistently with the rest of your suite.
    await page.locator(".figure").nth(1).hover();
    await expect(page.locator(".figure").nth(1).locator(".figcaption")).toBeVisible();

    // The direct form, which the source video used.
    await page.hover(".figure:nth-child(5)");
  });

  test("Step 3 — right-click is a click with an option", async ({ page }) => {
    await page.goto(CONTEXT);

    // The page answers a right-click with a JS alert, so catch it before clicking.
    let message = "";
    page.once("dialog", async (dialog) => {
      message = dialog.message();
      await dialog.accept();
    });

    await page.locator("#hot-spot").click({ button: "right" });

    await expect.poll(() => message).toBe("You selected a context menu");
  });

  test("Step 4 — the click options, in one place", async ({ page }) => {
    await page.goto(CONTEXT);

    const hotSpot = page.locator("#hot-spot");

    // button: "left" | "right" | "middle"
    await hotSpot.click({ button: "left" });
    // clickCount: 2 is a double-click; dblclick() is the readable form
    await hotSpot.click({ clickCount: 2 });
    await hotSpot.dblclick();
    // delay: hold the button down, for widgets that measure press duration
    await hotSpot.click({ delay: 120 });

    // All four completed without throwing — that is the assertion here.
    await expect(hotSpot).toBeVisible();
  });

  test("Step 5 — drag and drop", async ({ page }) => {
    await page.goto(DRAG);

    const columnA = page.locator("#column-a");
    const columnB = page.locator("#column-b");

    await expect(columnA.locator("header")).toHaveText("A");

    await columnA.dragTo(columnB);

    // The columns swap their contents, so A now holds B's header.
    await expect(columnA.locator("header")).toHaveText("B");
  });
});
`);

await runSpec("week4/generated/day2-mouse-actions.spec.ts");

import type { FrameLocator, Locator, Page } from "npm:playwright";

/** The frame boundary is resolved once, privately. Callers never learn it exists. */
class EditorPage {
  private readonly page: Page;
  private readonly frame: FrameLocator;
  readonly body: Locator;

  constructor(page: Page, frameSelector = "#mce_0_ifr") {
    this.page = page;
    this.frame = page.frameLocator(frameSelector);
    this.body = this.frame.locator("body");   // exposed as an ordinary Locator
  }

  async open(): Promise<void> {
    await this.page.goto("https://the-internet.herokuapp.com/iframe");
  }
}

/** A hover menu is a component, not a page — it appears on several screens. */
class HoverMenu {
  private readonly trigger: Locator;
  private readonly panel: Locator;

  constructor(page: Page, triggerSelector: string) {
    this.trigger = page.locator(triggerSelector);
    this.panel = this.trigger.locator(".figcaption");
  }

  /** Hovers AND waits for what the hover reveals — the classic missing step. */
  async open(): Promise<void> {
    await this.trigger.hover();
    await this.panel.waitFor({ state: "visible" });
  }

  caption(): Locator {
    return this.panel;
  }
}

